import sys

def main():
    data = sys.stdin.read().split()
    if not data:
        return
    idx = 0
    try:
        n = int(data[idx])
        idx += 1
    except:
        return
    arr = []
    for i in range(n):
        if idx < len(data):
            arr.append(data[idx])
            idx += 1
    print(' '.join(arr))

if __name__ == '__main__':
    main()
